WordHunterWoW_ENDesc_Item[169313] = "Equip: Your damaging abilities have a low chance to surround you with an Arcane Tempest for 20 sec, inflicting 6 Arcane damage every 2 sec to nearby enemies. The Tempest accelerates each time it strikes a lone enemy, dealing damage more frequently."
WordHunterWoW_ENDesc_Item[169314] = "Use: Channel latent magic for up to 4 sec, increasing your primary stat by 27. The duration is extended for each second spent channeling, up to 30 sec. (2 Min Cooldown)"
WordHunterWoW_ENDesc_Item[169315] = "Equip: Every 40 seconds, gain an absorb that prevents 369 Physical damage. If the absorb is consumed you gain Fanaticism, causing subsequent absorbs to prevent 10% more damage, up to 100%.\nUse: Declare Edict of the Sea Witch, causing this ability to instead absorb Magic damage and resetting Fanaticism. (40 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[169316] = "Equip: Defer 10 healing every 3 seconds. Moving releases deferred healing, restoring health to your 3 most injured allies."
WordHunterWoW_ENDesc_Item[169317] = "Equip: Your abilities have a chance to grant you 13 primary stat for 30 sec."
