WordHunterWoW_ENDesc_Item[183698] = "Use: Removes the target's restraints, freeing them."
WordHunterWoW_ENDesc_Item[183704] = "Use: Infuse a Wildseed of Regrowth with this spirit."
WordHunterWoW_ENDesc_Item[183714] = "Use: Teaches you how to summon a Withering Mire Creeper."
WordHunterWoW_ENDesc_Item[183715] = "Use: Teaches you how to summon this mount."
WordHunterWoW_ENDesc_Item[183716] = "Use: Adds this toy to your Toy Box.\n\nReturns you to your inn. Speak to an Innkeeper in a different place to change your home location.\n\nCan only be used by those pledged to the Venthyr."
WordHunterWoW_ENDesc_Item[183718] = "Use: Throw a ball of gooey gorm gunk at a target slowing their movement for 15 sec. Only usable on creatures outdoors in the Shadowlands.  (1 Min Cooldown)"
WordHunterWoW_ENDesc_Item[183723] = "Use: Infuse 250 stored Anima into your covenant's Reservoir."
WordHunterWoW_ENDesc_Item[183725] = "Use: Try to catch a moth! (2 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[183727] = "Use: Infuse 3 stored Anima into your covenant's Reservoir."
WordHunterWoW_ENDesc_Item[183733] = "Use: A typical alcoholic beverage."
WordHunterWoW_ENDesc_Item[183734] = "Use: Shatter the orb, taking the Stygia from it for yourself. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[183738] = "Use: Permanently enchants your chest to increase your Intellect by 3 and give your spells and abilities a chance to deal additional shadow damage. Cannot be applied to items lower than level 10."
WordHunterWoW_ENDesc_Item[183740] = "Use: Teaches you how to summon this mount."
WordHunterWoW_ENDesc_Item[183741] = "Use: Teaches you how to summon this mount."
WordHunterWoW_ENDesc_Item[183787] = "Use: Summons a Stygic Dampener that increases the damage taken by the Gorged Shadehound by 20% and reduces damage taken by anyone near it by 20%.\n\nUsable in the Prodigum and Pit of Anguish."
WordHunterWoW_ENDesc_Item[183790] = "Use: Summon Platter Master Stue to your location. (1 Hr Cooldown)"
WordHunterWoW_ENDesc_Item[183793] = "Use: Set out an Empyrean Refreshment to feed up to 35 people in your raid or party!\n\nRestores 0 health and 0 mana over 20 sec.  Must remain seated while eating. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[183797] = "Use: Mends the wounds of an injured ally."
WordHunterWoW_ENDesc_Item[183798] = "Use: Teaches you how to summon Battle Gargon Silessa as a mount."
WordHunterWoW_ENDesc_Item[183799] = "Use: Places a Shifting Catalyst that when used grants the ability to Essence Shift around the battlefield.\n\nUsable in the Soulstained Fields or Torturer's Hovel of The Maw."
WordHunterWoW_ENDesc_Item[183800] = "Use: Teaches you how to summon this mount."
