WordHunterWoW_ENDesc_Item[186662] = "Use: Attune yourself to the energies of the targeted Sanctum of Domination raid boss, increasing your Versatility by 24 when fighting that boss. This effect lasts for an entire week.\n\nYou can only use one Vantus Rune per week."
WordHunterWoW_ENDesc_Item[186672] = "Use: Leap forward on ephemeral wings, reducing fall speed for 10 sec. Then jump to a nearby location. (6 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[186673] = "Use: Restore the following memory to the Runecarver:\n\n Kindred Affinity\nYou and your Kindred Spirit each gain a bonus secondary stat based on their Covenant. This bonus is halved for your Kindred Spirit, however both bonuses are doubled while the bond is Empowered.\n\nKyrian: Mastery increased by 52.\nNight Fae: Haste increased by 6%.\nVenthyr: Critical Strike chance increased by 6%.\nNecrolord: Versatility increased by 6%."
WordHunterWoW_ENDesc_Item[186676] = "Use: Restore the following memory to the Runecarver:\n\n Toxic Onslaught\nWhen Sepsis expires on your target you gain Adrenaline Rush and Shadow Blades for 10 sec."
WordHunterWoW_ENDesc_Item[186678] = "Use: Mawforged Weapons aid you in combat for 2 min. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[186679] = "Use: Places a non-elite enemy target under your control for 2 min. When the rune fades, the controlled target explodes dealing damage to everyone nearby. (5 Min Cooldown)"
