WordHunterWoW_ENDesc_Item[202116] = "Equip: Your spells and abilities have a chance to increase your primary stat by 36 for 10 sec and reduce the cooldown of your combat potions by 10 sec."
WordHunterWoW_ENDesc_Item[202117] = "Equip: Your healing spells have a chance to mend your ally with arcane magic, restoring an additional 1,878 health."
WordHunterWoW_ENDesc_Item[202118] = "Equip: Taking damage has a chance to grant an arcane shield, absorbing the next 3,503 damage and lasting 12 sec."
WordHunterWoW_ENDesc_Item[202119] = "Equip: Your damaging spells and abilities have a chance to deal 1,251 Arcane damage."
WordHunterWoW_ENDesc_Item[202152] = "Use: Add a socket to a Dragonflight Season 1 item that does not already have one. Can be used on Helms, Necks, Bracers, Belts, or Rings."
WordHunterWoW_ENDesc_Item[202163] = "Use: Open the box and place the prize at your feet. (2 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[202167] = "Use: Collect the appearances of the Wanderer's Rosy Trappings."
WordHunterWoW_ENDesc_Item[202170] = "Use: Collect the appearances of the Vagabond's Rosy Threads."
WordHunterWoW_ENDesc_Item[202178] = "Use: Collect the appearances of the Vagabond's Carrot Threads."
WordHunterWoW_ENDesc_Item[202179] = "Use: Collect the appearances of the Wanderer's Carrot Trappings."
WordHunterWoW_ENDesc_Item[202182] = "Use: Melts paper down to sludge. (4 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[202186] = "Explodes when picked. And also other times."
WordHunterWoW_ENDesc_Item[202202] = "Use: Allows the user to see objects and creatures of interest that may be obscured from normal vision. (5 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[202207] = "Use: Adds this toy to your Toy Box.\n\nIncrease the size of your ordinary fishing bobber for 1 hour.\n\nCan be used with bobbers in your toy collection. (15 Min Cooldown)"
WordHunterWoW_ENDesc_Item[202247] = "Use: Filter for attune items and locations. (3 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[202252] = "Use: Attempt a civil negotiation with the captured rat in effort to obtain its closely guarded recipe. (5 Min Cooldown)"
WordHunterWoW_ENDesc_Item[202253] = "Use: Adds this toy to your Toy Box.\n\nTransforms you into a Winterpelt Furbolg for 5 min. (10 Min Cooldown)"
WordHunterWoW_ENDesc_Item[202255] = "Use: Teaches you how to summon and dismiss this companion."
WordHunterWoW_ENDesc_Item[202261] = "Use: Adds this toy to your Toy Box.\n\nThrow down your Warcraft Rumble Mini: Sneed. (1 Min Cooldown)"
WordHunterWoW_ENDesc_Item[202264] = "Equip: Your spells and abilities have a low chance to call forth a Winterpelt Defender to fight by your side for 30 sec."
WordHunterWoW_ENDesc_Item[202268] = "Use: Summons a Winterpelt totem at the target location for 20 sec. Party members within 10 yards have a high chance to deal 582 bonus Nature damage when dealing a harmful spell or ability.\n\nThe bonus damage is increased if the affected ally is a furbolg. (2 Min Cooldown)"
WordHunterWoW_ENDesc_Item[202270] = "Use: Lasso a tortoise to guide it back to the daycare."
WordHunterWoW_ENDesc_Item[202271] = "Use: Toss a coin at a Hired Bodyguard. (3 Sec Cooldown)"
