WordHunterWoW_ENDesc_Item[202280] = "Use: Unlocks this customization option for the Renewed Proto-Drake at the Rostrum of Transformation."
WordHunterWoW_ENDesc_Item[202282] = "Use: Smash the totem into an ally's wound, briefly stunning them and Healing them for 2,232.\n\nOnly usable outdoors. (2 Min Cooldown)"
WordHunterWoW_ENDesc_Item[202283] = "Use: Adds this toy to your Toy Box.\n\nEquip a pair of reading glasses. (3 Min Cooldown)"
WordHunterWoW_ENDesc_Item[202289] = "Use: Teaches you how to cook Firewater Sorbet."
WordHunterWoW_ENDesc_Item[202290] = "Use: Restores 53,571 health over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating, you will become well fed, increasing all secondary stats by 1 and growing in size."
WordHunterWoW_ENDesc_Item[202293] = "Use: Summon or dismiss Rusziona to travel the Dragon Isles with you. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[202309] = "Use: Adds this toy to your Toy Box.\n\nActivate the Doomsday Device. (5 Min Cooldown)"
