WordHunterWoW_ENDesc_Item[203996] = "Equip: Go with the flow, steadily rising towards High Tide or falling towards Low Tide every 30 seconds.\n\nAt Low Tide, your next harmful spell or ranged ability grants you 50 Critical Strike for 12 sec. \n\nAt High Tide, your next harmful spell or ranged ability launches a lava wave to crash upon your target dealing 1,473 Volcanic damage split between all nearby enemies. This damage is reduced if the lava wave travels less than 20 yds."
WordHunterWoW_ENDesc_Item[204000] = "Equip: Critically striking an enemy has a chance to shock them and 2 nearby enemies, dealing 338 Nature damage."
WordHunterWoW_ENDesc_Item[204001] = "Equip: Moving builds an electrical charge, causing your next damaging ability to also deal 437 Nature damage."
WordHunterWoW_ENDesc_Item[204002] = "Equip: Dealing damage has a chance to set the enemy on fire, dealing 526 Fire damage over 7 sec."
WordHunterWoW_ENDesc_Item[204003] = "Equip: Absorbing damage has a chance to coat you in lava, causing melee attackers to take 72 Fire damage for 6 sec."
WordHunterWoW_ENDesc_Item[204004] = "Equip: Successful interrupts exhale smoke, dealing 250 Fire damage to enemies within a 8 yd cone in front of you."
WordHunterWoW_ENDesc_Item[204005] = "Equip: Fire damage dealt by Primordial Stones is increased by 60%, and is now Chaos damage."
WordHunterWoW_ENDesc_Item[204006] = "Equip: Taking damage has a chance to shield yourself, absorbing 1,642 damage for 12 sec."
WordHunterWoW_ENDesc_Item[204007] = "Equip: Gaining an absorb shield from a Primordial Stone erupts the ground, dealing 781 Physical damage split between enemies within 5 yd.\n\nDamage is increased for each enemy struck, up to 5 enemies."
WordHunterWoW_ENDesc_Item[204009] = "Equip: Standing still for 3 seconds in combat steels yourself, absorbing 821 damage and increasing autoattack damage by 24 for 25 sec."
WordHunterWoW_ENDesc_Item[204010] = "Equip: Abilities have a chance to drench a nearby ally, healing them for 1,314 over 6 sec."
WordHunterWoW_ENDesc_Item[204011] = "Equip: Dealing damage has a chance to chill the enemy, dealing 490 Frost damage and slowing them by 15% for 6 sec."
WordHunterWoW_ENDesc_Item[204012] = "Equip: Gain a Frost shield every 20 sec that absorbs 1,095 damage and slows melee attackers by 15% for 5 sec."
WordHunterWoW_ENDesc_Item[204013] = "Equip: Receiving heals has a chance to exude steam, restoring 543 health to yourself and 2 nearby allies."
WordHunterWoW_ENDesc_Item[204014] = "Equip: Frost effects from Primordial Stones restore 45 mana over 3 sec."
WordHunterWoW_ENDesc_Item[204015] = "Equip: Being near a dying creature saps a portion of their mojo, and eventually crystallizes it."
WordHunterWoW_ENDesc_Item[204018] = "Equip: Dealing Magic damage has a chance to fire Arcane missiles for each Primordial Stone family you have equipped, each dealing 228 Arcane damage."
WordHunterWoW_ENDesc_Item[204019] = "Equip: Entering combat increases the tertiary stats of you and 4 nearby allies by 16 for 8 sec."
WordHunterWoW_ENDesc_Item[204020] = "Equip: Nature and healing effects from Primordial Stones restore 272 health of 5 nearby allies over 7 sec."
WordHunterWoW_ENDesc_Item[204021] = "Equip: Once every minute, moving near a corpse grants the Equip effects of the Desirous Blood, Cold Frost, and Pestilent Plague Stones for 25 sec.\n\nAlready having one of these effects instead increases its effectiveness by 75%."
WordHunterWoW_ENDesc_Item[204022] = "Equip: Dealing damage has a chance to infect the target with a plague that spreads to nearby enemies, dealing 292 Nature damage over 9 sec."
WordHunterWoW_ENDesc_Item[204025] = "Equip: Spells and abilities have a chance to cast a random Primordial Stone effect."
WordHunterWoW_ENDesc_Item[204027] = "Equip: Dealing damage has a chance to drain life, dealing 389 Shadow damage and healing you for that amount."
WordHunterWoW_ENDesc_Item[204029] = "Equip: Damaging effects from your Primordial Stones trigger one of your healing effects, and vice versa."
WordHunterWoW_ENDesc_Item[204030] = "Equip: Moving rallies the wind to your side, granting 4 Speed stacking up to 5 times."
WordHunterWoW_ENDesc_Item[204072] = "Use: Restores 53,571 health over 20 sec. Must remain seated while eating. If you spend at least 10 seconds eating, you will become well fed and gain 5 Intellect for 1 hour."
WordHunterWoW_ENDesc_Item[204073] = "Use: Teaches you how to cook Deviously Deviled Eggs."
