WordHunterWoW_ENDesc_Item[217600] = "Use: Soul Rot now resembles the Night Fae Covenant Ability."
WordHunterWoW_ENDesc_Item[217605] = "Use: Infuses the target with brilliance, increasing their Intellect by 4% for 1 hour.  \n\nIf the target is in your party or raid, all party and raid members will be affected. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[217606] = "Use: Infuses the target with vitality, increasing their Stamina by 4% for 1 hour.\n\nIf the target is in your party or raid, all party and raid members will be affected. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[217607] = "Use: Infuse a friendly target with the power of the wild, increasing their Versatility by 2% for 1 hour.\n\nIf target is in your party or raid, all party and raid members will be affected. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[217608] = "Use: Increases the attack power of all raid and party members within 100 yards by 4% for 1 hour. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[217612] = "Use: Teaches you how to summon this mount.  This mount changes depending on your Riding skill and location."
WordHunterWoW_ENDesc_Item[217698] = "Use: Awaken the power within Nasz'uro, the Unbound Legacy, increasing its item level to 502 and allowing it to be upgraded further."
WordHunterWoW_ENDesc_Item[217700] = "Use: Awaken the power within Fyr'alath the Dreamrender, increasing its item level to 502 and allowing it to be upgraded further."
WordHunterWoW_ENDesc_Item[217707] = "Use: Combine 5 of this item to forge an unblemished Null Stone."
WordHunterWoW_ENDesc_Item[217722] = "Weave this thread into your Cloak of Infinite Potential permanently increasing your Experience gained by 1%."
WordHunterWoW_ENDesc_Item[217723] = "Use: Adds this toy to your Toy Box.\n\nOccasionally don the wings of Xuen over the next 8 hrs. (10 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[217724] = "Use: Adds this toy to your Toy Box.\n\nOccasionally don the wings of Chi-Ji over the next 8 hrs. (10 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[217725] = "Use: Adds this toy to your Toy Box.\n\nOccasionally don the wings of Yu'lon over the next 8 hrs. (10 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[217726] = "Use: Adds this toy to your Toy Box.\n\nOccasionally don the wings of Niuzao over the next 8 hrs. (10 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[217730] = "Use: For 1 hour, your damage brands the target, increasing magic damage taken by 2%. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[217731] = "Use: For 1 hour, your damage weakens the target, increasing Physical damage taken by 4%. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[217732] = "Grants 30% of a random secondary stat to all party members within 40 yards for 30 sec."
WordHunterWoW_ENDesc_Item[217733] = "Increases movement and mount speed by 30% for all allies within 40 yards for 1 min."
WordHunterWoW_ENDesc_Item[217734] = "Grants 80% cooldown reduction on Cogwheel abilities and immunity to movement impairing and loss of control effects for 3 min."
WordHunterWoW_ENDesc_Item[217735] = "The next attack that reduces you below 35% health triggers Purged Violence\n\nPurged Violence:\nProtects the caster from all attacks and spells for 8 sec."
