WordHunterWoW_ENDesc_Item[226373] = "Use: Adds this toy to your Toy Box.\n\nThe mouthfeel of oil and the brininess of an oyster. Delicious.\n\nCosts 50 silver per gulp. (3 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[226393] = "Use: Equip a jetpack, allowing temporary flight within Undermine for 30 sec. Explodes upon expiration or landing. (5 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[226429] = "Use: Collect the appearances of the Ragged Harvest Golem Ensemble."
WordHunterWoW_ENDesc_Item[226471] = "Use: Collect the appearances of the Patched Harvest Golem Ensemble."
