WordHunterWoW_ENDesc_Item[226514] = "Use: Reveal the location of a Weave-Rat Cache on your map. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[226515] = "Use: Reveal the location of a Bounty Rumor on your map. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[226516] = "Use: Reveal the location of a Disruption Rumor on your map. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[226517] = "Use: Reveal the location of a Espionage Rumor on your map. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[226518] = "Use: Throw an implosion of various pheromones to stun guards in the City of Threads for 2 seconds, breaking you from combat.\n\n (1 Sec Cooldown)"
