WordHunterWoW_ENDesc_Item[232374] = "Use: Restores 4% of your maximum health every second over 20 sec. Must remain seated while eating. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[232375] = "Use: Restores 9 health over 30 sec.  Must remain seated while eating. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[232376] = "Use: Restores 50,000 mana over 20 sec. Must remain seated while drinking. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[232377] = "Use: This brew makes the drinker go into a rage for 5 minutes. Strong alcohol. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[232378] = "Use: Restores 30,000 health over 20 sec.\nMust remain seated while eating.\n (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[232380] = "Use: Restores 8 health over 30 sec. Must remain seated while eating. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[232385] = "Use: Restores 9 health over 30 sec.  Must remain seated while eating. (1 Sec Cooldown)"
WordHunterWoW_ENDesc_Item[232386] = "Use: Add a socket to a War Within Season 2 item that does not already have one. Can be used on Helms, Bracers, or Belts. Cannot be used on PvP equipment."
